//! ASCII texts around every shipped rule, with the verdict the Python implementation
//! gives each: on ASCII text the two must agree everywhere. Generated by
//! `compat/record_policy_fixtures.py matrix`; the cross-implementation suite asks
//! Python again for every verdict in the file.

use memriver_core::content_policy::secret_scanner::shannon_entropy;
use memriver_core::content_policy::{CachePolicy, Policy};

/// Every compiled rule is kept: these tests are about verdicts, which no way of keeping
/// compiled rules changes, and compiling a rule anew for every text would take minutes.
const KEEP: CachePolicy = CachePolicy::Lru(usize::MAX);
use serde_json::Value;

/// What stands in for one white-space character, in the order the fixture lists the
/// verdicts: ASCII white space, the four separators Python counts as white space, and
/// three controls it does not.
const SUBSTITUTES: [char; 13] = [
    '\t', '\n', '\u{b}', '\u{c}', '\r', ' ', '\u{1c}', '\u{1d}', '\u{1e}', '\u{1f}', '\0', '\u{8}',
    '\u{7f}',
];

fn lines() -> Vec<Value> {
    include_str!("fixtures/policy_ascii_matrix.jsonl")
        .lines()
        .map(|line| serde_json::from_str(line).expect("a fixture line"))
        .collect()
}

/// The texts with their verdicts; the file also holds entropies.
fn rows() -> Vec<Value> {
    let mut rows = lines();
    rows.retain(|row| row["text_hex"].is_string());
    rows
}

/// The text a fixture holds as the hex digits of its UTF-8 bytes: many have the shape of
/// a provider's token on purpose, and are not spelled out in a file that is published.
fn shown(hex: &Value) -> String {
    let hex = hex.as_str().expect("hex digits");
    let bytes = (0..hex.len())
        .step_by(2)
        .map(|at| u8::from_str_radix(&hex[at..at + 2], 16).expect("a hex byte"))
        .collect();
    String::from_utf8(bytes).expect("UTF-8")
}

#[test]
fn every_entropy_is_the_float_python_computes() {
    let mut checked = 0;
    for row in lines().iter().filter(|row| row["entropy"].is_string()) {
        let text = row["entropy"].as_str().unwrap();
        let bits = format!("{:016x}", shannon_entropy(text).to_bits());
        assert_eq!(bits, row["bits"].as_str().unwrap(), "{text:?}");
        checked += 1;
    }
    assert_eq!(checked, 300);
}

fn verdict(policy: &Policy, text: &str) -> Option<String> {
    policy.check(text, 8000).map(|rejection| rejection.rule_id)
}

/// `text` with the character at index `at` replaced.
fn substituted(text: &str, at: usize, by: char) -> String {
    assert!(text.is_ascii());
    let mut bytes = text.as_bytes().to_vec();
    bytes[at] = by as u8;
    String::from_utf8(bytes).unwrap()
}

#[test]
fn every_ascii_matrix_verdict_equals_python() {
    let policy = Policy::embedded().with_cache(KEEP);
    let (mut checked, mut refused) = (0, 0);
    for row in rows() {
        let text = shown(&row["text_hex"]);
        let text = text.as_str();
        assert!(text.is_ascii());
        assert_eq!(
            verdict(&policy, text).as_deref(),
            row["verdict"].as_str(),
            "{text:?}"
        );
        checked += 1;
        for position in row["subs"].as_array().into_iter().flatten() {
            let at = usize::try_from(position[0].as_u64().unwrap()).unwrap();
            let expected = position[1].as_array().unwrap();
            assert_eq!(expected.len(), SUBSTITUTES.len());
            for (by, expected) in SUBSTITUTES.iter().zip(expected) {
                let changed = substituted(text, at, *by);
                let found = verdict(&policy, &changed);
                assert_eq!(found.as_deref(), expected.as_str(), "{changed:?}");
                checked += 1;
                refused += usize::from(found.is_some());
            }
        }
    }
    assert_eq!(checked, 16469);
    // the matrix is not all one answer
    assert!(refused > 2000 && checked - refused > 2000, "{refused}");
}

#[test]
fn u001f_between_key_and_value_is_whitespace_as_in_python() {
    // where the four separators stand for a space the verdict is the space's, and a
    // control that is no white space gives another one somewhere
    let policy = Policy::embedded().with_cache(KEEP);
    let (mut as_space, mut unlike_controls) = (0, 0);
    for row in rows() {
        let text = shown(&row["text_hex"]);
        let text = text.as_str();
        for position in row["subs"].as_array().into_iter().flatten() {
            let at = usize::try_from(position[0].as_u64().unwrap()).unwrap();
            let space = verdict(&policy, &substituted(text, at, ' '));
            for separator in ['\u{1c}', '\u{1d}', '\u{1e}', '\u{1f}'] {
                let found = verdict(&policy, &substituted(text, at, separator));
                if space.is_some() && found == space {
                    as_space += 1;
                }
            }
            let backspace = verdict(&policy, &substituted(text, at, '\u{8}'));
            unlike_controls += usize::from(space.is_some() && backspace != space);
        }
    }
    assert!(as_space > 1000, "{as_space}");
    assert!(unlike_controls > 100, "{unlike_controls}");
    // and the plain case, spelled out
    for separator in [' ', '\u{1c}', '\u{1f}'] {
        let text = format!("password{separator}={separator}hunter2hunter2");
        assert_eq!(
            verdict(&policy, &text).as_deref(),
            Some("memriver-credential-assignment"),
            "{text:?}"
        );
    }
}

#[test]
fn the_six_endings_get_pythons_verdicts_and_the_dollar_decides_them_for_one_rule() {
    let policy = Policy::embedded().with_cache(KEEP);
    // a token last in the text, then: nothing, a line feed, two, a carriage return and
    // a line feed, a space, a line feed and another line -- for each rule with a `$`
    let mut by_rule: Vec<(String, Vec<Option<String>>)> = Vec::new();
    for row in rows().iter().filter(|row| row["tail"] == true) {
        let text = shown(&row["text_hex"]);
        let found = verdict(&policy, &text);
        assert_eq!(found.as_deref(), row["verdict"].as_str(), "{text:?}");
        let rule = row["rule"].as_str().unwrap();
        match by_rule.last_mut().filter(|(last, _)| last == rule) {
            Some((_, verdicts)) => verdicts.push(found),
            None => by_rule.push((rule.to_string(), vec![found])),
        }
    }
    assert_eq!(by_rule.len(), 154);
    assert!(by_rule.iter().all(|(_, verdicts)| verdicts.len() == 6));
    // What this shows about `$` is little. Nearly every rule ends in the vendored
    // `(?:[\x60'"\s;]|\\[nr]|$)`, where the white-space branch takes the line feed
    // itself: all six endings get one verdict, and the `$` decides nothing. It decides
    // for one rule only, whose token is refused at the end and before one final line
    // feed and not before anything else
    let decided: Vec<&str> = by_rule
        .iter()
        .filter(|(_, verdicts)| verdicts.iter().any(|verdict| *verdict != verdicts[0]))
        .map(|(rule, _)| rule.as_str())
        .collect();
    assert_eq!(decided, ["sidekiq-sensitive-url"]);
    let (_, sidekiq) = by_rule.iter().find(|(rule, _)| rule == decided[0]).unwrap();
    let refused: Vec<bool> = sidekiq.iter().map(Option::is_some).collect();
    assert_eq!(refused, [true, true, false, false, false, false]);
    // so the rule is stated on its own: one final line feed is the end, two are not
    let only = Policy::from_sources(&["[[rules]]\nid = \"r\"\nregex = 'tok[0-9]{4}$'\n"]).unwrap();
    let hit = |text: &str| only.check(text, 8000).is_some();
    assert!(hit("tok1234") && hit("tok1234\n"));
    assert!(!hit("tok1234\n\n") && !hit("tok1234\r\n") && !hit("tok1234 ") && !hit("tok1234\nx"));
}

#[test]
fn the_rule_with_an_entropy_threshold_refuses_by_the_entropy_of_each_candidate() {
    // texts no other rule can refuse: what is refused here is refused by the threshold
    let policy = Policy::embedded().with_cache(KEEP);
    let (mut refused, mut stored, mut later, mut neither) = (0, 0, 0, 0);
    for row in rows().iter().filter(|row| row["generic"].is_string()) {
        let text = shown(&row["text_hex"]);
        let found = verdict(&policy, &text);
        assert_eq!(found.as_deref(), row["verdict"].as_str(), "{text:?}");
        assert!(
            found.is_none() || found.as_deref() == Some("generic-api-key"),
            "{text:?}"
        );
        let measured = policy.measured("generic-api-key", &text);
        let expected: Vec<String> = row["measured_hex"]
            .as_array()
            .unwrap()
            .iter()
            .map(shown)
            .collect();
        assert_eq!(measured, expected, "{text:?}");
        let reaches: Vec<bool> = measured
            .iter()
            .map(|part| shannon_entropy(part) >= 3.5)
            .collect();
        // refused exactly when some candidate reaches the threshold
        assert_eq!(found.is_some(), reaches.contains(&true), "{text:?}");
        match row["generic"].as_str().unwrap() {
            "one" => {
                assert_eq!(reaches.len(), 1, "{text:?}");
                refused += usize::from(found.is_some());
                stored += usize::from(found.is_none());
            }
            // a first candidate below the threshold does not hide a later one above it
            "low-then-high" => {
                assert_eq!(reaches, [false, true], "{text:?}");
                later += 1;
            }
            "two-low" => {
                assert_eq!(reaches, [false, false], "{text:?}");
                neither += 1;
            }
            other => panic!("unknown kind {other}"),
        }
    }
    assert_eq!((refused, stored, later, neither), (40, 40, 12, 8));
}

#[test]
fn entropy_text_never_includes_the_consumed_newline() {
    let policy = Policy::embedded().with_cache(KEEP);
    let mut measured = 0;
    for row in rows().iter().filter(|row| row["measured_hex"].is_array()) {
        let text = shown(&row["text_hex"]);
        let text = text.as_str();
        let expected: Vec<String> = row["measured_hex"]
            .as_array()
            .unwrap()
            .iter()
            .map(shown)
            .collect();
        let found = policy.measured(row["rule"].as_str().unwrap(), text);
        assert_eq!(found, expected, "{text:?}");
        assert!(found.iter().all(|part| !part.contains('\n')));
        measured += found.len();
    }
    assert!(measured >= 4, "{measured}");
}
